(function(){
"use strict";
var TAG="HUPin";
var TEMPLATE='<$huwiki-hupin project=<<currentTiddler>>/>';
function text(s,n){return String(s==null?"":s).slice(0,n||5000);}
function number(x,min,max){var n=Number(x);return isFinite(n)?Math.min(max,Math.max(min,n)):min;}
function validTitle(t){t=text(t,180).trim();if(!t)throw new Error("Skriv titlen på en tiddler.");return t;}
function clampCoord(n){return Math.round(number(n,0,1000)*10)/10;}
function safeLink(s){s=text(s,2000).trim();return /^(https?:\/\/|data:image\/(png|jpeg|gif|webp|svg\+xml);|blob:)/i.test(s)?s:"";}
function defaultData(kind){return kind==="geo"?{version:2,kind:"geo",provider:"osm",center:[55.6761,10.5],zoom:6,pins:[]}:{version:2,kind:"image",source:"",sourceKind:"image",hotspots:[]};}
function normalizePoint(p){return [clampCoord(p&&p[0]),clampCoord(p&&p[1])];}
function cleanShape(v){
 if(!v||["rect","ellipse","polygon","pin"].indexOf(v.shape)<0)return null;
 var points=(Array.isArray(v.points)?v.points:[]).slice(0,90).map(normalizePoint);
 if((v.shape==="polygon"&&points.length<3)||(v.shape!=="polygon"&&points.length<(v.shape==="pin"?1:2)))return null;
 return {id:text(v.id,80)||"b"+Math.random().toString(36).slice(2,12),shape:v.shape,points:points,
  anchor:text(v.anchor,180),anchorPoints:Array.isArray(v.anchorPoints)&&v.anchorPoints.length===points.length?v.anchorPoints.map(normalizePoint):[],
  title:text(v.title,180),label:text(v.label,100),color:/^#[0-9a-f]{6}$/i.test(v.color)?v.color:"#e26c3a"};
}
function cleanPin(v){
 if(!v)return null;var lat=Number(v.lat),lon=Number(v.lon);
 if(!isFinite(lat)||!isFinite(lon))return null;
 return {id:text(v.id,80)||"p"+Math.random().toString(36).slice(2,12),lat:number(lat,-85.0511,85.0511),lon:number(lon,-180,180),title:text(v.title,180),label:text(v.label,100),color:/^#[0-9a-f]{6}$/i.test(v.color)?v.color:"#c85132"};
}
function cleanData(data){
 data=data||{};var kind=data.kind==="geo"?"geo":"image";var out=defaultData(kind);
 if(kind==="image"){
  out.source=text(data.source,2000);out.sourceKind=data.sourceKind==="pasteup"?"pasteup":"image";out.hotspots=(Array.isArray(data.hotspots)?data.hotspots:[]).slice(0,300).map(cleanShape).filter(Boolean);
 }else{
  out.provider=data.provider==="google"?"google":"osm";out.center=[number(data.center&&data.center[0],-85,85),number(data.center&&data.center[1],-180,180)];
  out.zoom=Math.round(number(data.zoom,2,18));out.pins=(Array.isArray(data.pins)?data.pins:[]).slice(0,400).map(cleanPin).filter(Boolean);
 }
 return out;
}
function read(wiki,title){var t=wiki.getTiddler(title);if(!t)return null;try{return cleanData(JSON.parse(t.fields["billedlink-data"]||"{}"));}catch(e){return null;}}
function write(wiki,Tiddler,title,data){title=validTitle(title);data=cleanData(data);
 var old=wiki.getTiddler(title),fields=old?Object.assign({},old.fields):{};
 fields.title=title;fields.type="text/vnd.tiddlywiki";fields.text=TEMPLATE;
 fields["billedlink-kind"]=data.kind;fields["billedlink-data"]=JSON.stringify(data);
 var tags=old?old.fields.tags||[]:[];if(typeof tags==="string")tags=$tw.utils.parseStringArray(tags);
 fields.tags=Array.from(new Set(tags.concat([TAG])));delete fields.modified;
 wiki.addTiddler(new Tiddler(fields));return title;
}
function linked(wiki,Tiddler,title,data,project){title=validTitle(title);
 var t=wiki.getTiddler(title);if(!t){wiki.addTiddler(new Tiddler({title:title,text:"Beskriv dette sted eller område her.",tags:["HUPin mål"],"billedlink-project":project}));return true;}
 return false;
}
function moveShape(shape,dx,dy){
 var p=shape.points||[],xs=p.map(function(a){return a[0];}),ys=p.map(function(a){return a[1];});
 if(!p.length)return shape;
 dx=Math.max(-Math.min.apply(null,xs),Math.min(1000-Math.max.apply(null,xs),dx));
 dy=Math.max(-Math.min.apply(null,ys),Math.min(1000-Math.max.apply(null,ys),dy));
 shape.points=p.map(function(a){return [clampCoord(a[0]+dx),clampCoord(a[1]+dy)];});
 return shape;
}
function pasteupBounds(wiki,source,anchor){
 if(!source||!anchor)return null;
 var master=wiki.getTiddler(source),layout=wiki.getTiddler(source+"/Layout");
 if(!master||!layout||!layout.fields[anchor])return null;
 var settings=wiki.getTiddlerData?wiki.getTiddlerData(source,{}):{};
 if(!settings||typeof settings!=='object'||Array.isArray(settings))settings={};
 var rows=Number(settings.rows||master.fields.rows||30),cols=Number(settings.cols||master.fields.cols||25);
 var parts=String(layout.fields[anchor]).split(",").slice(0,4).map(Number);
 if(parts.length!==4||parts.some(function(n){return !isFinite(n);})||rows<=0||cols<=0)return null;
 var top=(parts[0]-1)/rows*1000,left=(parts[1]-1)/cols*1000;
 var bottom=parts[2]/rows*1000,right=parts[3]/cols*1000;
 if(right<=left||bottom<=top)return null;
 return {x:left,y:top,w:right-left,h:bottom-top};
}
function pasteupFields(wiki,source){var t=wiki.getTiddler(source+"/Layout");if(!t)return [];
 return Object.keys(t.fields).filter(function(f){return !/^(title|text|type|created|modified|creator|modifier|tags)$/.test(f)&&pasteupBounds(wiki,source,f);}).sort();}
function toLocal(pts,b){return pts.map(function(pt){return [clampCoord((pt[0]-b.x)/b.w*1000),clampCoord((pt[1]-b.y)/b.h*1000)];});}
function toAbsolute(pts,b){return pts.map(function(pt){return [clampCoord(b.x+pt[0]/1000*b.w),clampCoord(b.y+pt[1]/1000*b.h)];});}
function displayShape(wiki,source,shape){var b=pasteupBounds(wiki,source,shape.anchor);
 if(!b||!shape.anchorPoints||shape.anchorPoints.length!==shape.points.length)return shape;
 var out=Object.assign({},shape);out.points=toAbsolute(shape.anchorPoints,b);return out;
}
function nudgeAnchored(wiki,source,shape,dx,dy){var b=pasteupBounds(wiki,source,shape.anchor);
 var displayed=displayShape(wiki,source,shape),obj={points:displayed.points.map(function(p){return p.slice();})};
 moveShape(obj,dx,dy);shape.points=obj.points;
 if(b)shape.anchorPoints=toLocal(shape.points,b);
 return shape;
}
exports.pasteupBounds=pasteupBounds;exports.pasteupFields=pasteupFields;exports.toLocal=toLocal;exports.toAbsolute=toAbsolute;exports.displayShape=displayShape;exports.nudgeAnchored=nudgeAnchored;
exports.moveShape=moveShape;exports.TAG=TAG;exports.TEMPLATE=TEMPLATE;exports.defaultData=defaultData;exports.cleanData=cleanData;exports.cleanShape=cleanShape;exports.cleanPin=cleanPin;exports.read=read;exports.write=write;exports.linked=linked;exports.safeLink=safeLink;exports.validTitle=validTitle;
})();
"},"$:/plugins/huwiki/hupin/geo-widget.js":{"title":"$:/plugins/huwiki/hupin/geo-widget.js","type":"application/javascript","module-type":"widget","text":"/*\
