(function(){"use strict";
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var engine=require("$:/plugins/huwiki/hupin/engine.js");
var ui=require("$:/plugins/huwiki/hupin/ui.js");
var leafletPromise=null,googlePromise=null;
function googleKey(){return ($tw.wiki.getTiddlerText("$:/config/HUWiki/HUPin/GoogleMapsApiKey","")||$tw.wiki.getTiddlerText("$:/config/HUWiki/BilledLink/GoogleMapsApiKey","")||"").trim();}
function loadGoogle(doc,key){
 if(window.google&&window.google.maps&&window.google.maps.importLibrary)return Promise.resolve(window.google.maps);
 if(googlePromise)return googlePromise;
 googlePromise=new Promise(function(resolve,reject){
  var script=doc.createElement("script");script.async=true;
  script.src="https://maps.googleapis.com/maps/api/js?key="+encodeURIComponent(key)+"&v=weekly&loading=async";
  script.onload=function(){if(window.google&&window.google.maps&&window.google.maps.importLibrary)resolve(window.google.maps);else reject(new Error("Google Maps blev ikke indlæst."));};
  script.onerror=function(){reject(new Error("Google Maps kunne ikke indlæses. Kontrollér API-nøgle og domænetilladelser."));};
  doc.head.appendChild(script);
 }).catch(function(err){googlePromise=null;throw err;});return googlePromise;
}

function loadLeaflet(doc){
  if(leafletPromise) {
    return leafletPromise;
  }

  // Leaflet 1.9.4's official CSS hash. A rejected stylesheet leaves tiles and
  // markers in normal document flow even when the JavaScript loaded correctly.
  // https://leafletjs.com/examples/quick-start/
  var css;
  var script;
  leafletPromise = new Promise(function(resolve,reject) {
    css = doc.createElement("link");
    css.rel = "stylesheet";
    css.href = "https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css";
    css.integrity = "sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=";
    css.crossOrigin = "anonymous";

    css.onerror = function() {
      reject(new Error("Leaflets design kunne ikke indlæses. Prøv igen med internetforbindelse."));
    };
    css.onload = function() {
      // Another plugin may already provide Leaflet. Its presence alone does
      // not prove this document has the stylesheet needed by our map.
      if(window.L && window.L.map) {
        resolve(window.L);
        return;
      }

      script = doc.createElement("script");
      script.src = "https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js";
      script.integrity = "sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=";
      script.crossOrigin = "anonymous";
      script.onload = function() {
        if(window.L && window.L.map) {
          resolve(window.L);
        } else {
          reject(new Error("Kortbiblioteket blev ikke indlæst."));
        }
      };
      script.onerror = function() {
        reject(new Error("Kunne ikke hente Leaflet. Kort kræver internet i denne version."));
      };
      doc.head.appendChild(script);
    };
    doc.head.appendChild(css);
  }).catch(function(error) {
    // Remove only this loader's own elements, allowing an explicit later retry.
    if(css && css.parentNode) {
      css.parentNode.removeChild(css);
    }
    if(script && script.parentNode) {
      script.parentNode.removeChild(script);
    }
    leafletPromise = null;
    throw error;
  });

  return leafletPromise;
}
function Geo(parseTreeNode,options){this.initialise(parseTreeNode,options);}
Geo.prototype=new Widget();Geo.prototype.execute=function(){};
Geo.prototype.render=function(parent,nextSibling){
 this.parentDomNode=parent;this.computeAttributes();this.execute();this.project=this.getAttribute("project",this.getVariable("currentTiddler")||"");
 this.root=this.document.createElement("div");this.root.className="bl-widget bl-geo";parent.insertBefore(this.root,nextSibling);this.domNodes=[this.root];
 this.edit=false;this.pending=null;this.selected="";this.message="";this.map=null;this.provider="";this.draw();
};
Geo.prototype.refresh=function(changed){var attrs=this.computeAttributes();if($tw.utils.count(attrs)){this.refreshSelf();return true;}if(changed&&changed[this.project]){this.draw();return true;}return false;};
Geo.prototype.removeMap=function(){if(this.map){if(this.provider==="osm"){try{this.map.off();this.map.remove();}catch(ignore){}}this.map=null;this.provider="";}this.viewport=null;};
Geo.prototype.onDestroy=function(){this.removeMap();this.root=null;};
Geo.prototype.draw=function(){
 var self=this,data=engine.read($tw.wiki,this.project);this.removeMap();if(!this.root)return;this.root.replaceChildren();
 if(!data||data.kind!=="geo"){ui.notice(this.root,"Dette er ikke et geografisk HUPin-projekt.",true);return;}
 var head=ui.elem(this.root,"div","bl-head"),left=ui.elem(head,"div","bl-head-text");ui.elem(left,"strong",null,"HUPin · Kort og tiddlere");ui.elem(left,"span","bl-muted",data.pins.length+" pins · Klik i kortet for at tilføje");
 ui.button(head,this.edit?"✓ Afslut redigering":"✎ Redigér pins",function(){self.edit=!self.edit;self.pending=null;self.draw();},this.edit?"bl-primary":"");
 if(this.message)ui.notice(this.root,this.message,false);
 if(this.edit){
  var settings=ui.elem(this.root,"div","bl-geo-settings"),sel=ui.elem(settings,"select","bl-input bl-provider");
  [["osm","OpenStreetMap (uden Google-nøgle)"],["google","Google Maps (kræver API-nøgle)"]].forEach(function(item){var o=ui.elem(sel,"option",null,item[1]);o.value=item[0];});
  sel.value=data.provider;sel.addEventListener("change",function(){data.provider=sel.value;engine.write($tw.wiki,$tw.Tiddler,self.project,data);self.draw();});
  ui.button(settings,"Gem aktuelt kortudsnit",function(){if(self.viewport){var v=self.viewport();data.center=v.center;data.zoom=v.zoom;engine.write($tw.wiki,$tw.Tiddler,self.project,data);self.message="Kortudsnittet er gemt.";self.draw();}});
 }
 if(data.provider==="google"&&!googleKey()){
  ui.notice(this.root,"Google Maps-demo: Tilføj en browserbegrænset Google Maps API-nøgle i $:/config/HUWiki/HUPin/GoogleMapsApiKey. Indtil da vises alle redigerbare pins på OpenStreetMap.",false);
 }
 var mapEl=ui.elem(this.root,"div","bl-map"),footer=ui.elem(this.root,"div","bl-geo-footer");
 ui.elem(footer,"div","bl-help","Kortdata © OpenStreetMap-bidragsydere. Internetforbindelse kræves. Vælg en pin for at åbne dens tiddler.");
 var form=ui.elem(this.root,"div","bl-geo-form");
 if(this.edit&&data.pins.length){var list=ui.elem(this.root,"div","bl-list");data.pins.forEach(function(p,i){ui.button(list,(i+1)+". "+(p.label||p.title||"Pin"),function(){self.selected=p.id;self.pending=null;self.showPinForm(form,data,p);},self.selected===p.id?"bl-active":"");});}
 var paintToken=mapEl;
 if(data.provider==="google"&&googleKey()){
  this.drawGoogle(mapEl,form,data);
  return;
 }
 loadLeaflet(this.document).then(function(L){if(!self.root||!self.root.contains(paintToken))return;
  var map=L.map(mapEl,{scrollWheelZoom:false}).setView(data.center,data.zoom);self.map=map;self.provider="osm";self.viewport=function(){var p=map.getCenter();return {center:[p.lat,p.lng],zoom:map.getZoom()};};
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> contributors'}).addTo(map);
  data.pins.forEach(function(p){
   var pinIcon=L.divIcon({className:"bl-leaflet-icon",html:'<span class="bl-marker" style="background:'+p.color+'" aria-hidden="true"></span>',iconSize:[24,32],iconAnchor:[12,31]});
   var marker=L.marker([p.lat,p.lon],{icon:pinIcon,title:p.label||p.title||"Pin",draggable:self.edit}).addTo(map);
   marker.on("dragend",function(ev){var pt=ev.target.getLatLng();p.lat=pt.lat;p.lon=pt.lng;engine.write($tw.wiki,$tw.Tiddler,self.project,data);self.selected=p.id;self.showPinForm(form,data,p);});
   marker.on("click",function(){if(self.edit){self.selected=p.id;self.pending=null;self.showPinForm(form,data,p);}else if(p.title){ui.navigate(self,p.title,self.project);}else{self.edit=true;self.selected=p.id;self.showPinForm(form,data,p);}});
  });
  map.on("click",function(e){self.selected="";self.pending={lat:e.latlng.lat,lon:e.latlng.lng};self.showPinForm(form,data,null);});
  setTimeout(function(){if(self.map===map)map.invalidateSize();},60);
 }).catch(function(e){if(self.root&&self.root.contains(mapEl)){mapEl.textContent="Kortet kunne ikke indlæses: "+e.message;mapEl.className="bl-map bl-map-error";}});
};
Geo.prototype.drawGoogle=function(mapEl,form,data){
 var self=this;
 loadGoogle(this.document,googleKey()).then(async function(G){
  if(!self.root||!self.root.contains(mapEl))return;
  await G.importLibrary("maps");
  var markerApi=await G.importLibrary("marker");
  if(!self.root||!self.root.contains(mapEl))return;
  var map=new G.Map(mapEl,{center:{lat:data.center[0],lng:data.center[1]},zoom:data.zoom,mapId:"DEMO_MAP_ID",streetViewControl:false,mapTypeControl:false});
  self.map=map;self.provider="google";
  self.viewport=function(){var pos=map.getCenter();return {center:[pos.lat(),pos.lng()],zoom:map.getZoom()};};
  data.pins.forEach(function(p){
   var content=mapEl.ownerDocument.createElement("div");content.className="bl-gmarker";content.style.background=p.color;
   content.textContent="●";content.setAttribute("aria-label",p.label||p.title||"Pin");
   var marker=new markerApi.AdvancedMarkerElement({map:map,position:{lat:p.lat,lng:p.lon},title:p.label||p.title||"Pin",content:content,gmpClickable:true,gmpDraggable:self.edit});
   marker.addListener("click",function(){if(self.edit){self.selected=p.id;self.pending=null;self.showPinForm(form,data,p);}else if(p.title){ui.navigate(self,p.title,self.project);}});
   marker.addListener("dragend",function(){if(!self.edit)return;var pos=marker.position;p.lat=typeof pos.lat==="function"?pos.lat():pos.lat;p.lon=typeof pos.lng==="function"?pos.lng():pos.lng;engine.write($tw.wiki,$tw.Tiddler,self.project,data);self.showPinForm(form,data,p);});
  });
  map.addListener("click",function(e){if(!e.latLng)return;self.selected="";self.pending={lat:e.latLng.lat(),lon:e.latLng.lng()};self.showPinForm(form,data,null);});
 }).catch(function(e){if(self.root&&self.root.contains(mapEl)){mapEl.className="bl-map bl-map-error";mapEl.textContent="Google Maps kunne ikke startes: "+e.message+" Prøv OpenStreetMap i Redigér pins.";}});
};
Geo.prototype.showPinForm=function(host,data,pin){
 var self=this;host.replaceChildren();var v=pin||this.pending;if(!v)return;
 ui.elem(host,"h4",null,pin?"Redigér pin":"Ny pin · placering valgt");
 ui.elem(host,"div","bl-muted","Breddegrad "+Number(v.lat).toFixed(5)+" · Længdegrad "+Number(v.lon).toFixed(5));
 var title=ui.input(host,"Tilknyttet tiddler",pin?pin.title:"",function(){},{placeholder:"Skriv en eksisterende eller ny tiddlertitel"});
 var label=ui.input(host,"Navn på pin",pin?pin.label:"",function(){},{placeholder:"Fx Her ligger skolen"});
 var color=ui.input(host,"Pinfarve",pin?pin.color:"#c85132",function(){},{type:"color"});
 var actions=ui.elem(host,"div","bl-tools");
 ui.button(actions,pin?"Gem ændringer og åbn tiddler":"Opret pin og åbn tiddler",function(){
  var target;try{target=engine.validTitle(title.value);}catch(e){ui.notice(host,e.message,true);title.focus();return;}
  if(pin){pin.title=target;pin.label=label.value;pin.color=color.value;}
  else{var p=engine.cleanPin({lat:v.lat,lon:v.lon,title:target,label:label.value,color:color.value});data.pins.push(p);self.pending=null;}
  engine.write($tw.wiki,$tw.Tiddler,self.project,data);engine.linked($tw.wiki,$tw.Tiddler,target,data,self.project);
  self.draw();ui.navigate(self,target,self.project);
 },"bl-primary");
 ui.button(actions,"Annuller",function(){self.pending=null;self.selected="";host.replaceChildren();});
 if(pin){ui.button(actions,"Slet pin",function(){data.pins=data.pins.filter(function(p){return p.id!==pin.id;});self.selected="";engine.write($tw.wiki,$tw.Tiddler,self.project,data);self.draw();},"bl-danger");}
};
exports["huwiki-hupin-geo"]=Geo;exports["huwiki-billedlink-geo"]=Geo;
})();
