(function(){"use strict";
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var engine=require("$:/plugins/huwiki/hupin/engine.js");
var ui=require("$:/plugins/huwiki/hupin/ui.js");
function ImageMap(parseTreeNode,options){this.initialise(parseTreeNode,options);}
ImageMap.prototype=new Widget();
ImageMap.prototype.execute=function(){};
ImageMap.prototype.render=function(parent,nextSibling){
 this.parentDomNode=parent;this.computeAttributes();this.execute();this.project=this.getAttribute("project",this.getVariable("currentTiddler")||"");
 this.root=this.document.createElement("div");this.root.className="bl-widget";parent.insertBefore(this.root,nextSibling);this.domNodes=[this.root];
 this.edit=false;this.tool="rect";this.pending=[];this.selected="";this.message="";this.draft=null;this.step=1;this.draw();
};
ImageMap.prototype.refresh=function(changed){
 var attrs=this.computeAttributes();if($tw.utils.count(attrs)){this.refreshSelf();return true;}
 if(changed&&(changed[this.project]||changed[this.assetTitle]||changed[this.assetTitle+"/Layout"]||changed[this.assetTitle+"/Styles"])){this.draw();return true;}return false;
};
function sourceUrl(wiki,title){
 var url=engine.safeLink(title);if(url)return url;
 var t=wiki.getTiddler(title);if(!t)return "";
 var c=t.fields._canonical_uri;if(c)return engine.safeLink(c);
 var type=String(t.fields.type||""),raw=t.fields.text||"";
 if(type==="image/svg+xml")return "data:image/svg+xml;charset=utf-8,"+encodeURIComponent(raw);
 if(/^image\/(png|jpeg|gif|webp)$/.test(type))return "data:"+type+";base64,"+raw.replace(/\s/g,"");
 return "";
}
function pt(e,svg){var b=svg.getBoundingClientRect();return [Math.round(1000*(e.clientX-b.left)/b.width),Math.round(1000*(e.clientY-b.top)/b.height)].map(function(n){return Math.max(0,Math.min(1000,n));});}
function shapePath(s){var p=s.points;if(s.shape==="pin"){return "M"+p[0][0]+" "+(p[0][1]-18)+" a18 18 0 1 0 0.1 0 Z";}
 if(s.shape==="rect"){var a=p[0],b=p[1];return "M"+a[0]+" "+a[1]+" H"+b[0]+" V"+b[1]+" H"+a[0]+" Z";}
 if(s.shape==="polygon")return "M"+p.map(function(a){return a.join(" ");}).join(" L")+" Z";
 var a=p[0],b=p[1],cx=(a[0]+b[0])/2,cy=(a[1]+b[1])/2,rx=Math.max(2,Math.abs(a[0]-b[0])/2),ry=Math.max(2,Math.abs(a[1]-b[1])/2);
 return "M"+(cx-rx)+" "+cy+" a"+rx+" "+ry+" 0 1 0 "+(2*rx)+" 0 a"+rx+" "+ry+" 0 1 0 -"+(2*rx)+" 0";
}
function addShape(self,points){var data=engine.read($tw.wiki,self.project);if(!data)return;
 var shape=engine.cleanShape({id:"zone-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,7),shape:self.tool,points:points,title:"",label:"Nyt område"});
